package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                         // PIC X len=1 = "N"
var WsFirstFlag string = "Y"                       // PIC X len=1 = "Y"
var WsPrevBranch string = "  "                     // PIC X(2) len=2 = SPACES
var WsPrevAcct string = "    "                    // PIC X(4) len=4 = SPACES
var WsBal decimal.Decimal = decimal.NewFromInt(0)       // PIC S9(7)V99 len=9 = 0
var WsBranchTot decimal.Decimal = decimal.NewFromInt(0) // PIC S9(9)V99 len=11 = 0
var WsGrandTot decimal.Decimal = decimal.NewFromInt(0)  // PIC S9(9)V99 len=11 = 0
var WsSkipped int64 = 0                                // PIC 99 len=2 = 0
var WsAmtEd string                                     // PIC ZZ,ZZ9.99 len=9
var WsBalEd string                                     // PIC -Z,ZZZ,ZZ9.99 len=13
var WsTotEd string                                     // PIC -ZZZ,ZZZ,ZZ9.99 len=15

var ledgerRecs []LedgerRec
var recIdx int
var currentRecord LedgerRec

func isInputDone() bool   { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func formatMagnitude(absVal decimal.Decimal, magPic string) string {
	dotIdx := strings.Index(magPic, ".")
	var intPic, decPic string
	if dotIdx >= 0 {
		intPic = magPic[:dotIdx]
		decPic = magPic[dotIdx+1:]
	} else {
		intPic = magPic
		decPic = ""
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	decDigits := 0
	for _, ch := range decPic {
		if ch == 'Z' || ch == '9' {
			decDigits++
		}
	}
	trunc := absVal.Truncate(int32(decDigits))
	var s string
	if decDigits > 0 {
		s = trunc.StringFixed(int32(decDigits))
	} else {
		s = trunc.StringFixed(0)
	}
	var intPartStr, fracPartStr string
	if decDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intPartStr = parts[0]
		if len(parts) > 1 {
			fracPartStr = parts[1]
		} else {
			fracPartStr = strings.Repeat("0", decDigits)
		}
		if len(fracPartStr) < decDigits {
			fracPartStr = fracPartStr + strings.Repeat("0", decDigits-len(fracPartStr))
		} else if len(fracPartStr) > decDigits {
			fracPartStr = fracPartStr[:decDigits]
		}
	} else {
		intPartStr = s
		fracPartStr = ""
	}
	if len(intPartStr) > intDigits {
		intPartStr = intPartStr[len(intPartStr)-intDigits:]
	} else if len(intPartStr) < intDigits {
		intPartStr = strings.Repeat("0", intDigits-len(intPartStr)) + intPartStr
	}
	intIdx := 0
	decIdx := 0
	suppressing := true
	var out strings.Builder
	for i, ch := range magPic {
		switch ch {
		case 'Z', '9':
			beforeDot := dotIdx == -1 || i < dotIdx
			if beforeDot {
				d := intPartStr[intIdx]
				intIdx++
				if ch == 'Z' {
					if suppressing && d == '0' {
						out.WriteByte(' ')
					} else if suppressing && d != '0' {
						out.WriteByte(d)
						suppressing = false
					} else {
						out.WriteByte(d)
					}
				} else { // '9'
					out.WriteByte(d)
					suppressing = false
				}
			} else {
				d := fracPartStr[decIdx]
				decIdx++
				out.WriteByte(d)
			}
		case ',':
			if suppressing {
				out.WriteByte(' ')
			} else {
				out.WriteByte(',')
			}
		case '.':
			out.WriteByte('.')
			suppressing = false
		default:
			out.WriteRune(ch)
		}
	}
	return out.String()
}

func formatEdited(val decimal.Decimal, picture string) string {
	if len(picture) == 0 {
		return ""
	}
	if picture[0] == '-' || picture[0] == '+' {
		signChar := picture[0]
		magPic := picture[1:]
		magStr := formatMagnitude(val.Abs(), magPic)
		var signOut string
		if val.Sign() < 0 && !val.IsZero() {
			signOut = "-"
		} else {
			if signChar == '-' {
				signOut = " "
			} else {
				signOut = "+"
			}
		}
		return signOut + magStr
	}
	return formatMagnitude(val.Abs(), picture)
}

func storeDecimal(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	v = v.Truncate(scale)
	if v.IsZero() {
		return decimal.NewFromInt(0)
	}
	signNeg := v.Sign() < 0
	absStr := v.Abs().StringFixed(scale)
	var intPart, fracPart string
	if scale > 0 {
		dotIdx := strings.LastIndex(absStr, ".")
		if dotIdx >= 0 {
			intPart = absStr[:dotIdx]
			fracPart = absStr[dotIdx+1:]
		} else {
			intPart = absStr
			fracPart = strings.Repeat("0", int(scale))
		}
	} else {
		intPart = absStr
	}
	if len(intPart) > intDigits {
		intPart = intPart[len(intPart)-intDigits:]
	}
	var newStr string
	if scale > 0 {
		if len(fracPart) < int(scale) {
			fracPart = fracPart + strings.Repeat("0", int(scale)-len(fracPart))
		}
		newStr = intPart + "." + fracPart
	} else {
		newStr = intPart
	}
	if signNeg {
		newStr = "-" + newStr
	}
	nd, err := decimal.NewFromString(newStr)
	if err != nil {
		return v
	}
	return nd
}

func parseAmt(s string) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.NewFromInt(0)
	}
	n, err := strconv.ParseInt(trimmed, 10, 64)
	if err != nil {
		var b strings.Builder
		for _, ch := range trimmed {
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		if b.Len() == 0 {
			return decimal.NewFromInt(0)
		}
		n, _ = strconv.ParseInt(b.String(), 10, 64)
	}
	return decimal.New(n, -2)
}

func loadLedgerFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			ledgerRecs = []LedgerRec{}
			return
		}
		fmt.Fprintf(os.Stderr, "error reading input.dat: %v\n", err)
		os.Exit(1)
	}
	if len(data) == 0 {
		ledgerRecs = []LedgerRec{}
		return
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	lines := strings.Split(content, "\n")
	endIsNewline := len(content) > 0 && content[len(content)-1] == '\n'
	nLines := len(lines)
	ledgerRecs = make([]LedgerRec, 0, nLines)
	for idx, line := range lines {
		if idx == nLines-1 && line == "" && endIsNewline {
			continue
		}
		recStr := line
		if len(recStr) < 14 {
			recStr = recStr + strings.Repeat(" ", 14-len(recStr))
		} else if len(recStr) > 14 {
			recStr = recStr[:14]
		}
		brBranch := recStr[0:2]
		brAcct := recStr[2:6]
		brType := recStr[6:7]
		brAmtStr := recStr[7:14]
		brAmt := parseAmt(brAmtStr)
		rec := LedgerRec{
			BrBranch: brBranch,
			BrAcct:   brAcct,
			BrType:   brType,
			BrAmt:    brAmt,
		}
		ledgerRecs = append(ledgerRecs, rec)
	}
}

func ReadPara() {
	if recIdx < len(ledgerRecs) {
		currentRecord = ledgerRecs[recIdx]
		recIdx++
	} else {
		WsEofFlag = "Y"
	}
}

func PostPara() {
	WsAmtEd = formatEdited(currentRecord.BrAmt, "ZZ,ZZ9.99")
	switch currentRecord.BrType {
	case "D":
		WsBal = storeDecimal(WsBal.Add(currentRecord.BrAmt), 7, 2)
		line := currentRecord.BrAcct + " D " + WsAmtEd
		fmt.Printf("%s\n", line)
	case "C":
		WsBal = storeDecimal(WsBal.Sub(currentRecord.BrAmt), 7, 2)
		line := currentRecord.BrAcct + " C " + WsAmtEd
		fmt.Printf("%s\n", line)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		line := currentRecord.BrAcct + " ? SKIPPED"
		fmt.Printf("%s\n", line)
	}
}

func AcctBreakPara() {
	WsBalEd = formatEdited(WsBal, "-Z,ZZZ,ZZ9.99")
	line := "  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd
	fmt.Printf("%s\n", line)
	WsBranchTot = storeDecimal(WsBranchTot.Add(WsBal), 9, 2)
	WsBal = decimal.NewFromInt(0)
}

func BranchBreakPara() {
	WsTotEd = formatEdited(WsBranchTot, "-ZZZ,ZZZ,ZZ9.99")
	line := " BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd
	fmt.Printf("%s\n", line)
	WsGrandTot = storeDecimal(WsGrandTot.Add(WsBranchTot), 9, 2)
	WsBranchTot = decimal.NewFromInt(0)
}

func GrandPara() {
	WsTotEd = formatEdited(WsGrandTot, "-ZZZ,ZZZ,ZZ9.99")
	line := "GRAND TOTAL:" + WsTotEd
	fmt.Printf("%s\n", line)
	line2 := "SKIPPED: " + fmt.Sprintf("%02d", WsSkipped)
	fmt.Printf("%s\n", line2)
}

func ProcessPara() {
	if isFirstRecord() {
		WsPrevBranch = currentRecord.BrBranch
		WsPrevAcct = currentRecord.BrAcct
		WsFirstFlag = "N"
	} else {
		if currentRecord.BrBranch != WsPrevBranch {
			AcctBreakPara()
			BranchBreakPara()
			WsPrevBranch = currentRecord.BrBranch
			WsPrevAcct = currentRecord.BrAcct
		} else {
			if currentRecord.BrAcct != WsPrevAcct {
				AcctBreakPara()
				WsPrevAcct = currentRecord.BrAcct
			}
		}
	}
	PostPara()
	ReadPara()
}

func MainPara() {
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	if !isFirstRecord() {
		AcctBreakPara()
		BranchBreakPara()
	}
	GrandPara()
}

func main() {
	loadLedgerFile()
	MainPara()
}
